def compute(vars):
    old = vars["v1"]
    new = vars["v2"]

    if old == 0:
        return {"value": None, "trace": {"old": old, "new": new}}

    change_ratio = (new - old) / old
    percent_change = change_ratio * 100

    return {
        "value": percent_change,
        "trace": {
            "old": old,
            "new": new,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
